import alkahest as ak
import alkahest.number_theory as nt

def show(label, r):
    if hasattr(r, 'value'):
        print(f"{label}: value={r.value!r} steps={len(getattr(r,'steps') or [])} cert={bool(getattr(r,'certificate',None))}")
    else:
        print(f"{label}: {type(r).__name__} {r!r}"[:200])

pool = ak.ExprPool()
x = pool.symbol("x"); k = pool.symbol("k"); n = pool.symbol("n")

show("series exp", ak.series(ak.parse("exp(x)", pool, {"x":x}), x, pool.integer(0), 5))

try:
    show("solve", ak.solve(ak.parse("x^2 - 4", pool, {"x":x}), [x]))
except Exception as ex: print("solve ERR:", type(ex).__name__, str(ex)[:200])

try:
    show("sum_def", ak.sum_definite(ak.parse("k^2", pool, {"k":k}), (k, pool.integer(1), n)))
except Exception as ex: print("sum_def ERR:", type(ex).__name__, str(ex)[:200])
try:
    show("sum_indef", ak.sum_indefinite(ak.parse("k", pool, {"k":k}), k))
except Exception as ex: print("sum_indef ERR:", type(ex).__name__, str(ex)[:200])

print("isprime(2^127-1):", nt.isprime(2**127-1))
print("factorint(2^32-1):", nt.factorint(2**32-1))

# groebner via solve of system
try:
    r = ak.solve([ak.parse("x + y - 2", pool, {"x":x,"y":(y:=pool.symbol('y'))}), ak.parse("x^2 + y^2 - 5", pool, {"x":x,"y":y})], [x, y])
    show("solve system", r)
except Exception as ex: print("solve sys ERR:", type(ex).__name__, str(ex)[:300])

# numeric check helper: evaluate got vs expected at points
r = ak.simplify(ak.parse("(x^2-1)/(x-1)", pool, {"x":x}))
print("steps sample:", [s for s in r.steps][:2])
try:
    val = ak.numpy_eval([r.value], {x: [2.0, 3.5]})
    print("numpy_eval:", val)
except Exception as ex: print("numpy_eval ERR:", type(ex).__name__, str(ex)[:200])
